INSERT OR REPLACE INTO Language_en_US (Tag, Text) VALUES
-- Keldur Hall
('TXT_KEY_BUILDING_KELDUR_HALL', '켈뒤르 홀'),
('TXT_KEY_BUILDING_KELDUR_HALL_HELP', '건설 가능한 지형: [COLOR_CYAN]툰드라[ENDCOLOR], [COLOR_NEGATIVE_TEXT]평원[ENDCOLOR][NEWLINE]이 불가사의가 지어진 도시 주변 모든 툰드라 타일의 [ICON_FOOD] 식량과 [ICON_PRODUCTION] 생산력이 [COLOR_POSITIVE_TEXT]1[ENDCOLOR] 증가하며, 모든 설원 타일마다 도시에 [ICON_FOOD] 식량, [ICON_PRODUCTION] 생산력을 [COLOR_POSITIVE_TEXT]1[ENDCOLOR] 제공합니다. [NEWLINE]모든 도시의 마을에 [ICON_FOOD] 식량+2
[NEWLINE][NEWLINE]모든 도시의 [ICON_RESEARCH] 과학의 10%만큼 [ICON_FOOD] 식량이 증가합니다.'),
('TXT_KEY_BUILDING_KELDUR_HALL_PEDIA', '켈뒤르 홀은 아이슬란드 남부에 위치한 유서 깊은 잔디집으로, 독특한 건축 양식과 깊은 문화적 의미로 유명합니다. 12세기로 거슬러 올라가는 이 건물은 아이슬란드에서 현존하는 가장 오래된 농가 중 하나입니다. 전통적인 아이슬란드 방식으로 지어진 이 건물은 잔디 벽과 목재 구조로 이루어져 있어 혹독한 날씨를 견딜 수 있도록 설계되었습니다. 이 홀은 한때 유력한 족장들이 거주하던 곳으로, 강력한 오디 가문과 관련이 있는 것으로 여겨집니다. 탈출 또는 저장 용도로 사용되었을 가능성이 있는 지하 통로는 이곳의 신비로움과 역사적 매력을 더해줍니다.
[NEWLINE][NEWLINE]오랜 역사 속에서 켈뒤르는 사가 시대를 포함한 아이슬란드 중세의 산증인이었습니다. 고유의 모습 유지를 위한 신중한 보존 작업이 이루어졌으며, 이를 통해 방문객들은 초기 아이슬란드 농촌 생활을 엿볼 수 있습니다. 현재는 아이슬란드 국립박물관이 관리하며, 문화유산지로 지정되어 있습니다. 관광객들과 역사 애호가들은 이곳의 소박한 매력에 매료되어 과거 주민들의 이야기를 접하고 수세기 동안 거의 변하지 않은 주변 풍경을 탐방합니다.'),
('TXT_KEY_BUILDING_KELDUR_HALL_QUOTE', '[NEWLINE]"겨울밖에 모르고 살아온 사람의 마음은 정말 차가워질 수 있다."[NEWLINE] - 벤자민 알리레 사엔스[NEWLINE]'),
--======================================================================================================================
-- Nipisat
--======================================================================================================================
('TXT_KEY_BUILDING_NIPISAT', '니피삿'),
('TXT_KEY_BUILDING_NIPISAT_HELP', '건설 가능한 지형 [COLOR_CYAN]툰드라[ENDCOLOR], [COLOR_CYAN]해안[ENDCOLOR]
[NEWLINE][NEWLINE]이 불가사의가 지어진 도시 주변 모든 툰드라 타일의 [ICON_GOLD] 골드가 [COLOR_POSITIVE_TEXT]1[ENDCOLOR] 증가하며, 모든 설원 타일의  [ICON_FOOD] 식량과 [ICON_GOLD] 골드가 [COLOR_POSITIVE_TEXT]1[ENDCOLOR] 증가합니다.[NEWLINE]모든 도시의 어선에 +1 [ICON_PRODUCTION] 생산력,  [ICON_CULTURE_LOCAL] 국경 성장[NEWLINE][COLOR_CYAN]고고학[ENDCOLOR] 발견 시 +6 [ICON_CULTURE] 문화.[NEWLINE][NEWLINE]모든 [ICON_RES_DEER] 사슴 자원: +1 [ICON_PRODUCTION] 생산력, +1 [ICON_CULTURE] 문화'),
('TXT_KEY_BUILDING_NIPISAT_PEDIA', '그린란드 서해안 시시미우트 근처에 위치한 니피삿은 북극 선사 문화에 대한 통찰을 제공하는 중요한 고고학 유적지입니다. 약 4,000년 전으로 거슬러 올라가는 삿캑(Saqqaq) 문화의 유적이 광범위하게 남아 있는 곳으로, 북극 초기 거주민들의 생활 방식, 생계 수단, 기술 등을 잘 보여주는 가장 보존 상태가 뛰어난 삿캑 문화 유적지 중 하나입니다. 니피삿에서의 발굴을 통해 석기, 뼈, 주거지의 흔적 등 다양한 유물이 발견되었으며, 이는 삿캑 사람들이 북극의 혹독한 환경에 어떻게 적응했는지를 보여줍니다.
[NEWLINE][NEWLINE]삿캑 문화 외에도, 약 1,000년 전 삿캑 문화를 계승한 툴레(Thule) 문화의 흔적도 발견되었습니다. 툴레인들은 현대 이누이트의 조상으로, 니피삿에서의 이들의 존재는 이 지역에서의 인간 거주와 적응의 연속성을 나타냅니다. 니피삿에서의 발견은 선사시대 북극 지역 집단 간의 문화적 전환과 상호작용을 이해하는 데 기여하며, 2018년 유네스코 세계문화유산으로 등재되어 그 역사적 가치를 인정받았습니다.'),
('TXT_KEY_BUILDING_NIPISAT_QUOTE', '[NEWLINE]"카리부는 늑대를 먹여 살리지만, 늑대가 카리부를 강하게 만든다."[NEWLINE] - 이누이트 속담[NEWLINE]'),
--======================================================================================================================
-- Temple of Heracles Akragatos
--======================================================================================================================
('TXT_KEY_BUILDING_AKRAGATOS', '헤라클레스 아크라가토스 신전'),
('TXT_KEY_BUILDING_AKRAGATOS_HELP', '건설 가능한 지형: [COLOR_CYAN]언덕[ENDCOLOR] [NEWLINE][NEWLINE][COLOR_POSITIVE_TEXT]개척자[ENDCOLOR]가 1명 출현합니다. 모든 도시에서 정착 유닛 생성 시 [NEWLINE]도시의 [ICON_PEACE] 신앙력만큼 추가 [ICON_PRODUCTION]생산력을 얻습니다.[NEWLINE]모든 성소에서 +1 [ICON_FOOD] 식량, +1 [ICON_CULTURE] 문화, +1 [ICON_GOLDEN_AGE] 황금기 포인트를 얻습니다.[NEWLINE][NEWLINE][COLOR_CYAN]고고학[ENDCOLOR] 발견 시 +3 [ICON_TOURISM] 관광'),
('TXT_KEY_BUILDING_AKRAGATOS_PEDIA', '아크라가토스의 헤라클레스 신전은 이탈리아 시칠리아의 신들의 계곡에 위치한 고대 그리스 아크라가토스 식민지에서 가장 오래되고 숭배받는 건축물 중 하나입니다. 기원전 6세기 말에 건설된 이 도릭 양식의 신전은 그리스 신화의 신적 영웅 헤라클레스에게 헌정되었습니다. 수세기 동안 자연 재해와 인간 활동으로 큰 피해를 입었지만, 신전의 남은 기둥들은 고대 그리스 건축의 위대함을 증명하는 상징으로 여전히 남아 있습니다. 이 신전은 원래 38개의 기둥으로 둘러싸인 주랑과 중앙에 헤라클레스 동상이 있던 셀라가 있었습니다. [NEWLINE][NEWLINE]헤라클레스 신전은 역사적 및 건축적 의의뿐만 아니라, 지역의 종교적 관습과 신화와도 깊은 연관이 있습니다. 전설에 따르면, 신전에는 아크라가토스 사람들에 의해 매우 숭배받던 유명한 헤라클레스 동상이 있었으며, 이 동상은 그 지역 신앙의 중심이었습니다. 이 신전은 1920년대에 여러 차례 복원 작업을 거쳐 남아있는 기둥들을 보존하고 폐허를 안정시키는 작업이 진행되었습니다. 현재 헤라클레스 신전은 유네스코 세계문화유산에 등재된 신들의 계곡의 일부로, 고대의 웅장함을 감상하고 지중해에서 가장 중요한 고고학적 유적지 중 하나의 역사를 탐험하려는 전 세계 방문객들의 발길을 끌고 있습니다.'),
('TXT_KEY_BUILDING_AKRAGATOS_QUOTE', '[NEWLINE]"반대편에는 아름답게 만들어진 청동 헤라클레스상이 있었으며, 그것은 내가 믿기에는 미로의 작품이라 전해지고, 확실히 그랬다. 또한 그 신들 앞에는 작은 제단들이 있었는데, 이는 성당의 신성함을 누구에게나 알려줄 수 있었다." [NEWLINE] - 키케로 [NEWLINE]'),
--======================================================================================================================
-- Piscina Mirabilis
--======================================================================================================================
('TXT_KEY_BUILDING_PISCINA_MIR', '피시나 미라빌리스'),
('TXT_KEY_BUILDING_PISCINA_MIR_HELP', '건설 가능한 지형 [COLOR_CYAN]해안[ENDCOLOR]; 요구 건물: [COLOR_CYAN]송수로[ENDCOLOR] [NEWLINE][NEWLINE]이 도시에 인접한 해군 유닛은 행동 여부와 상관없이 매 턴 10 포인트씩 체력을 회복합니다. [NEWLINE]모든 도시의 [ICON_FOOD] 식량 생산량 10%만큼 [ICON_GREAT_ADMIRAL] 위대한 제독 점수가 증가합니다. [NEWLINE]모든 송수로에 +2 [ICON_PRODUCTION] 생산력이 추가됩니다.'),
('TXT_KEY_BUILDING_PISCINA_MIR_PEDIA', '피시나 미라빌리스는 이탈리아 나폴리 근처 바콜리에 위치한 로마 공학의 뛰어난 예이자 세계에서 가장 큰 고대 저수조 중 하나입니다. 기원전 1세기 아우구스투스 시대에 건설된 이 거대한 지하 구조물은 인근 미세눔 항구에 주둔한 로마 함대를 위한 주요 물 저장고 역할을 했습니다. 이 저수조는 약 12,600 입방미터의 물을 저장할 수 있었으며, 아펜니노 산맥의 샘에서 카파니아의 인구 밀집 지역으로 물을 운반하는 아쿠아 아우구스타 수로에서 공급받았습니다. 피시나 미라빌리스는 48개의 거대한 기둥이 대칭 그리드로 배치된 광대한 아치형 실들의 네트워크를 특징으로 하며, 로마인들의 고도의 수리 및 건축 기술을 보여줍니다. [NEWLINE][NEWLINE]피시나 미라빌리스의 인상적인 규모와 건설은 고대 로마에서 물 관리의 중요성과 일상 생활과 군사 작전을 지원한 정교한 인프라를 강조합니다. 저수조 내부는 높은 아치형 천장과 웅장한 기둥들로 이루어져 있어 거대한 지하 대성당과 같아 방문객들에게 경외감을 줍니다. 수세기 동안 피시나 미라빌리스는 역사가, 건축가, 관광객들에게 매혹의 대상이 되었으며, 로마 공학의 독창성과 기지의 증거로 남아 있습니다. 오늘날 이곳은 보호받는 역사적 기념물로서 고대 로마의 기술력과 문화적 우선순위를 엿볼 수 있게 합니다.'),
('TXT_KEY_BUILDING_PISCINA_MIR_QUOTE', '[NEWLINE]"교회가 종교인 것이 수로의 벽돌이 그 안을 흐르는 물인 것과 같지 않다."[NEWLINE] - 헨리 워드 비처[NEWLINE]'),
--======================================================================================================================
-- Banaue Rice Terraces
--======================================================================================================================
('TXT_KEY_BUILDING_BANAUE', '바나우에 쌀 테라스'),
('TXT_KEY_BUILDING_BANAUE_HELP', '지형: [COLOR_CYAN]산[ENDCOLOR] 개선: [COLOR_CYAN]농장[ENDCOLOR] [NEWLINE][NEWLINE]이 불가사의가 지어진 도시의 인근 언덕에 [ICON_RES_RICE] 쌀 자원 3개가 생성됩니다. [NEWLINE]모든 곡물 창고는 +2 [ICON_FOOD] 식량을 얻습니다. [NEWLINE][NEWLINE]모든 [ICON_RES_RICE] 쌀: +1 [ICON_FOOD] 식량, +2 [ICON_CULTURE] 문화.'),
('TXT_KEY_BUILDING_BANAUE_PEDIA', '바나우에 쌀 테라스는 해발 5000피트, 이파가오 산악지대의 약 4000평방마일을 차지하고 있습니다. 이 테라스는 약 2000년의 역사를 자랑하며, 고대 원주민 이푸가오족에 의해 만들어졌습니다. 오늘날에도 여전히 고대의 관개 시스템을 통해 비가 내리는 숲에서 물을 공급받고 있습니다. 고대 테라스는 최소한의 장비와 대부분 손으로만 만들어졌다는 것이 일반적인 믿음입니다. 테라스를 끝에서 끝까지 이어 놓으면 지구의 적도를 반쯤 둘 수 있다고 전해집니다. 이푸가오 문화는 쌀을 중심으로 형성되어 있으며, 쌀을 기르고 소비하는 모든 농업 의례와 젊은 세대에게 쌀을 다루는 여러 잔치를 소개해왔습니다. [NEWLINE][NEWLINE]오늘날 이 테라스는 여전히 이푸가오 사람들에게 쌀과 채소를 농사짓는 데 사용되고 있습니다. 그러나 더 많은 이푸가오 사람들이 농업을 다른 산업들보다 덜 매력적이라고 여기고 있습니다. 이로 인해 테라스가 서서히 침식되고 있으며, 특히 계단 부분이 가장 큰 영향을 받았습니다. 이 사이트에 대한 관리 필요성이 커졌습니다. 2010년에는 가뭄이라는 더 큰 문제가 발생하여 테라스가 3월까지 완전히 마르게 되었습니다.'),
('TXT_KEY_BUILDING_BANAUE_QUOTE', '[NEWLINE]"쌀 한 알은 농부의 이마에서 떨어지는 땀 한 방울이다." [NEWLINE] - 중국 속담 [NEWLINE]'),
--======================================================================================================================
-- Saint Catherine's Monastery
--======================================================================================================================
('TXT_KEY_BUILDING_ST_CATHERINE', '성 카타리나 수도원'),
('TXT_KEY_BUILDING_ST_CATHERINE_HELP', '특수: [COLOR_YIELD_PRODUCTION]성지[ENDCOLOR][NEWLINE][NEWLINE]건설된 도시에 무료 [COLOR_POSITIVE_TEXT]수도원[ENDCOLOR]이 제공됩니다. [NEWLINE][ICON_GREAT_WORK] 도시 내 위대한 작품은 +2 [ICON_CULTURE] 문화와 [ICON_PEACE] 신앙을 생성합니다. [NEWLINE][ICON_VP_GREATWRITING] 위대한 문학 작품 슬롯 2개를 제공합니다. [COLOR_POSITIVE_TEXT]테마 일치 시[ENDCOLOR] +4 [ICON_FOOD] 식량과 [ICON_PEACE] 신앙을 추가로 획득합니다.'),
('TXT_KEY_BUILDING_ST_CATHERINE_PEDIA', '이집트 시나이 반도의 시나이산 기슭에 위치한 성 카타리나 수도원은 세계에서 가장 오래도록 운영되어 온 기독교 수도원 중 하나입니다. 6세기에 비잔틴 황제 유스티니아누스 1세에 의해 설립되었으며, 기독교 순교자인 알렉산드리아의 성 카타리나의 유물이 기적적으로 이곳으로 옮겨진 데서 이름이 유래했습니다. 이 수도원은 초기 기독교 시대의 고대 필사본, 성상, 예술품 등 풍부한 역사적·종교적 유산을 보유하고 있습니다. 또한 모세가 신과 대화했다고 전해지는 불타는 떨기나무가 있어 기독교인과 유대인 모두에게 신성한 장소로 여겨집니다. [NEWLINE][NEWLINE]건축적으로 성 카타리나 수도원은 침입자로부터 주민과 보물을 보호하기 위해 요새처럼 설계된 복합 건축물입니다. 성당, 모스크, 방대한 초기 필사본을 소장한 도서관, 수도사들의 생활 공간 등이 담긴 성벽으로 둘러싸여 있습니다. 이 수도원 도서관은 바티칸에 이어 필사본의 중요성과 고대성에서 두 번째로 꼽힙니다. 유네스코 세계문화유산으로 지정된 성 카타리나 수도원은 순례, 학술 연구, 영적 헌신의 중심지로서 전 세계 방문객들이 그 풍부한 역사와 종교적 중요성에 관심을 가지고 방문합니다.'),
('TXT_KEY_BUILDING_ST_CATHERINE_QUOTE', '[NEWLINE]"믿음을 순수하게 지키려면 사람은 수도원으로 은퇴하는 것이 낫다."[NEWLINE] - 월터 립만[NEWLINE]'),
('TXT_KEY_THEMING_BONUS_ST_CATHERINE', '시나이 필사본'),
('TXT_KEY_THEMING_BONUS_ST_CATHERINE_HELP', '보너스를 최대화하려면, 모든 위대한 작품 슬롯을 당신이 창작한 문학 작품으로 채우십시오.'),
--======================================================================================================================
-- Songyue Pagoda 
--======================================================================================================================
('TXT_KEY_UNIT_JAR_HESHANG', '허샹'),
('TXT_KEY_BUILDING_SONGYUE_PAGODA', '송위 탑'),
('TXT_KEY_BUILDING_SONGYUE_PAGODA_HELP', '특수: [COLOR_YIELD_PRODUCTION]성지[ENDCOLOR][NEWLINE][NEWLINE]건설된 도시에 무료 [COLOR_POSITIVE_TEXT]파고다[ENDCOLOR]가 제공됩니다. [NEWLINE][COLOR_POSITIVE_TEXT]{TXT_KEY_UNIT_JAR_HESHANG}[ENDCOLOR]이라는 민간 유닛을 받으며, 이 유닛은 성지를 건설하는 데 사용될 수 있습니다. [NEWLINE]모든 도시의 [ICON_VP_SCIENTIST]과학자 전문가로부터 +2 [ICON_PEACE] 신앙을 얻습니다. [NEWLINE]모든 도시의 성지로부터 +3 [ICON_RESEARCH] 과학을 얻습니다.'),
('TXT_KEY_BUILDING_SONGYUE_PAGODA_PEDIA', '중국 허난성 송산에 위치한 송위 탑은 중국에서 알려진 가장 오래된 벽돌 탑으로, 북위 시대인 서기 523년경에 지어졌습니다. 이 고대 구조물은 중국 초기 불교 건축의 증거로서, 한족과 중앙아시아의 영향을 혼합한 양식을 반영합니다. 탑은 당시 흔했던 사각형 탑과 달리 원형 평면을 가지며, 12층으로 우아하게 점점 가늘어지는 형태이고 각 층은 독특한 처마로 구분되어 있습니다. 송위 탑의 정교한 벽돌 공예와 아치 및 받침대의 사용은 당대 고급 기술을 보여주며, 중국 건축의 초기 발전 단계를 나타냅니다. [NEWLINE][NEWLINE]건축적으로 송위 탑은 우아하고 혁신적인 디자인으로 중요하며, 이후 중국 전역의 탑 건축에 영향을 주었습니다. 탑 내부에는 중앙 기둥과 좁은 회랑이 있어 신도들이 탑을 돌며 예배할 수 있게 합니다. 이 설계는 구조적 안정성을 제공하여 수세기 동안 자연적 마모와 지진을 견딜 수 있게 했습니다. 불교가 중국에 전파된 상징으로서 송위 탑은 문화적·역사적 중요성을 지닌 기념물이자, 그 역사적 맥락과 건축적 의미를 이해하려는 학자, 건축가, 관광객들을 끌어들입니다. 2010년에는 ‘천지 중심 등봉의 역사적 기념물’의 일부로 유네스코 세계문화유산에 등재되었습니다.'),
('TXT_KEY_BUILDING_SONGYUE_PAGODA_QUOTE', '[NEWLINE]"사원은 하늘과 땅이 만나는 지점이다."[NEWLINE] - 데이비드 A. 베드나[NEWLINE]'),
--======================================================================================================================
-- Horyu-ji
--======================================================================================================================
('TXT_KEY_BUILDING_HORYUJI', '호류지'),
('TXT_KEY_BUILDING_HORYUJI_HELP', '건설 가능한 지형: [COLOR_CYAN]강[ENDCOLOR]이 인접한 [COLOR_CYAN]평지[ENDCOLOR][NEWLINE][NEWLINE]이 도시에서 믿는 [ICON_RELIGION] 종교의 개종력이 25% 증가합니다.[NEWLINE]무료 [COLOR_POSITIVE_TEXT]파고다[ENDCOLOR]가 제공됩니다. [NEWLINE]선교사 또는 종교재판관 유닛 구매 시 시대에 따라 증가하는 [ICON_CULTURE] 문화를 획득합니다.[NEWLINE]모든 도시의 [ICON_VP_WRITER] 작가 전문가로부터 +2 [ICON_PEACE] 신앙을 얻습니다.'),
('TXT_KEY_BUILDING_HORYUJI_PEDIA', '호류지는 일본 나라 현에 위치한 일본에서 가장 중요하고 역사적인 불교 사원 중 하나입니다. 607년 초기 일본 불교의 핵심 인물인 쇼토쿠 태자가 창건했으며, 일본에 불교 교리를 전파하기 위해 세워졌습니다. 원래 건물은 670년에 화재로 손상되었으나 신속히 재건되었고, 많은 건물들이 1,300년 이상 보존되어 왔습니다. 사원 단지에는 세계에서 가장 오래된 목조 건축물 중 일부가 있으며, 오층탑과 금당(콘도)에는 아스카 시대의 귀중한 불상과 유물이 보관되어 있습니다. [NEWLINE][NEWLINE]호류지는 그 역사적, 문화적, 건축적 중요성으로 1993년에 유네스코 세계문화유산으로 지정되었습니다. 사원 단지는 두 개의 주요 구역으로 나뉘는데, 가장 오래된 건물이 위치한 서쪽 구역인 사이인 가란과 동쪽 구역인 토인 가란(꿈의 전당인 유메도노 포함)입니다. 불교 학문과 예술의 중심지로서 호류지는 여전히 활발한 예배 장소이며 일본의 깊은 영적·건축 유산의 상징으로 남아 있습니다.'),
('TXT_KEY_BUILDING_HORYUJI_QUOTE', '[NEWLINE]"세 보배인 부처님, 가르침, 그리고 승가를 진심으로 공경하라."[NEWLINE] - 쇼토쿠 태자[NEWLINE]'),
('TXT_KEY_GRAND_HORYUJI_BONUS_HEADER', '호류지 [ICON_CULTURE]'),
('TXT_KEY_GRAND_HORYUJI_BONUS_BODY', '{@2_unitName} 유닛으로부터 +{@1_num} [ICON_CULTURE] 문화를 획득합니다.'),
--======================================================================================================================
-- Kyz Kala
--======================================================================================================================
('TXT_KEY_BUILDING_KYZ_KALA', '위대한 키즈 칼라'),
('TXT_KEY_BUILDING_KYZ_KALA_HELP', '건설 가능한 지형: [COLOR_NEGATIVE_TEXT]해안[ENDCOLOR], [COLOR_NEGATIVE_TEXT]호수[ENDCOLOR] 특성: [COLOR_CYAN]오아시스[ENDCOLOR]. [NEWLINE][NEWLINE]+2 [ICON_GREAT_GENERAL] 위대한 장군 포인트 [NEWLINE]건설된 도시에는 [COLOR_POSITIVE_TEXT]무료[ENDCOLOR] 성이 제공됩니다. [NEWLINE]제국 전역의 오아시스에서 +1 [ICON_PRODUCTION] 생산력, [ICON_CULTURE] 문화, [ICON_GOLDEN_AGE] 황금기 포인트. [NEWLINE]이 도시에서 건물을 건설할 때 +25 [ICON_FOOD] 식량이 제공되며, 이는 시대에 따라 증가합니다.'),
('TXT_KEY_BUILDING_KYZ_KALA_PEDIA', '위대한 키즈 칼라는 투르크메니스탄의 UNESCO 세계문화유산인 메르에 위치한 여러 비슷한 구조물 중 하나로, "코쉬크"(köshk)로 알려져 있는 진흙벽돌로 된 성곽 건물입니다. 이 기념물의 건설 시기와 용도에 대해서는 현재 몇 가지 추측이 존재합니다. 이 건물은 기원후 6세기에서 8세기 사이, 사산왕조 말기 또는 초기 이슬람 시대에 지어진 것으로 생각되며, 1221년 몽골의 메르 약탈까지 사용된 것으로 보입니다. 도시 성벽 밖에 위치해 있으며, 최근 발굴에서는 내부에 여러 개의 구분된 방과 바닥 표면, 계단 등이 발견되어 요새화된 거주지로 기능했을 가능성이 높습니다.'),
('TXT_KEY_BUILDING_KYZ_KALA_QUOTE', '[NEWLINE]"그러나 이 세상은 우리가 듣는 이야기와 같으니, 사람들의 악행과 그들의 영광은 사라진다." [NEWLINE] - 아불 카셈 페르도우시 [NEWLINE]'),
--======================================================================================================================
-- Shaolin Temple
--======================================================================================================================
('TXT_KEY_BUILDING_SHAOLIN', '소림사'),
('TXT_KEY_BUILDING_SHAOLIN_HELP', '지형: [COLOR_CYAN]산[ENDCOLOR] 도시: [COLOR_CYAN]플레이어의 대중 종교를 채택한 도시[ENDCOLOR] [NEWLINE][NEWLINE]이 불가사의가 지어진 도시에서 생성된 유닛은 [COLOR_POSITIVE_TEXT]자유[ENDCOLOR] 승급을 얻습니다. [NEWLINE]모든 도시의 모든 유닛은 +20 XP를 받습니다. [NEWLINE]모든 도시에서 [ICON_PEACE] 신앙의 10%만큼 [ICON_GREAT_GENERAL] 위대한 장군 포인트가 추가됩니다.'),
('TXT_KEY_BUILDING_SHAOLIN_PEDIA', '소림사는 1,500년 이상의 풍부한 역사를 자랑하며, 495년 북위(北魏) 시대에 시작되었습니다. 이 시기, 효문제는 인도 승려 바투오(불타바드라)에게 허락을 주어, 중국 허난성의 소호산 기슭에 사원을 건립하게 했습니다. 바투오는 소림사를 불교 연구와 수행의 중요한 중심지로 만들었고, 이후 중국에서 가장 유명한 사원 중 하나가 되는 기초를 마련했습니다. 32년 후, 또 다른 중요한 인물이 도착했습니다: 인도 승려 보디다르마(중국에서는 다모로 알려짐)로, 그는 소림사에서 선불교(Chan Buddhism)를 처음 전파한 첫 번째 선조가 되어, 소림사의 정신적 성격을 근본적으로 변화시키고 선불교의 발상지로서 명성을 확립했습니다. [NEWLINE][NEWLINE]소림사는 세계적으로 무술 전통으로 유명하지만, 그 무술 체계의 역사적 발전은 인기 있는 전설이 말하는 것보다 훨씬 복잡합니다. 현대 무술 역사학자들은 보디다르마가 소림사에서 무술을 창시했다는 널리 퍼진 믿음이 실제로 17세기 기공서에서 비롯되었으며, 20세기에 대중화되었음을 보여주었습니다. 보디다르마의 실제 기여는 승려들이 건강을 유지하는 데 도움이 되는 기공 기반 운동을 개발한 것으로, 이는 전투 기술보다는 요가와 더 비슷했습니다. 소림사의 무술 전통은 여러 세기를 거쳐 점진적으로 발전했으며, 다양한 격투 기술들이 통합되어 전설적인 이야기들이 말하는 것보다 훨씬 더 늦게 체계화되었습니다. 이 역사적 설명에도 불구하고, 소림사는 여전히 불교 학습의 중심지이자 중국 무술 문화의 상징으로 깊은 의미를 지니고 있습니다.'),
('TXT_KEY_BUILDING_SHAOLIN_QUOTE', '[NEWLINE]"신앙은 인간의 마음이 구상하고 믿을 수 있는 것을 성취할 수 있게 해준다." [NEWLINE] - 브루스 리 [NEWLINE]'),
