-- Watson Research Center
--======================================================================================================================
('TXT_KEY_BUILDING_WATSON_RC', '왓슨 연구소'),
('TXT_KEY_BUILDING_WATSON_RC_HELP', '지형: [COLOR_CYAN]평지[ENDCOLOR]; 건물: [COLOR_CYAN]연구소[ENDCOLOR][NEWLINE][NEWLINE]모든 도시의 과학 생산량이 10% 증가합니다. [NEWLINE]모든 도시의 과학의 10%만큼 생산력으로 추가됩니다. [NEWLINE]모든 도시의 제조 시설과 마을은 +4 [ICON_RESEARCH] 과학을 얻습니다.'),
('TXT_KEY_BUILDING_WATSON_RC_PEDIA', '토머스 J. 왓슨 연구소는 IBM의 주요 연구 시설로, 전 CEO인 토머스 J. 왓슨 시니어의 이름을 따서 명명되었습니다. 1961년에 설립되어 IBM 연구의 중심지 역할을 하며, 컴퓨팅, 인공지능, 양자 컴퓨팅, 반도체 기술 분야의 최첨단 연구에 집중하고 있습니다. 뉴욕 요크타운 하이츠에 위치한 본 캠퍼스는 유명 건축가 에로 사리넨이 설계한 미래 지향적이고 파도 모양의 구조를 갖추고 있습니다. 매사추세츠 케임브리지와 캘리포니아 알마덴에도 관련 연구소가 있습니다. 수십 년 동안 왓슨 연구소는 1997년 체스 챔피언 개리 카스파로프를 이긴 IBM의 딥블루, 2011년 제퍼디! 우승을 차지한 왓슨 AI 등 획기적인 연구 성과를 냈습니다. [NEWLINE][NEWLINE]과학기술 연구 분야의 글로벌 리더로서 왓슨 연구소는 클라우드 컴퓨팅, 사이버보안, AI 윤리, 양자 컴퓨팅 분야의 발전을 계속 이끌고 있습니다. 대학, 정부, 기업과 협력해 혁신의 경계를 확장하고 있으며, 왓슨은 양자 컴퓨팅 연구의 본거지로 암호학과 재료 과학 등 분야에서 혁신적인 양자 프로세서를 개발 중입니다. 기초 및 응용 연구에 강력히 집중하며, 왓슨 연구소는 컴퓨팅과 인공지능의 미래를 형성하는 기술 혁신의 최전선에 서 있습니다.'),
('TXT_KEY_BUILDING_WATSON_RC_QUOTE', '[NEWLINE]"우리가 무엇을 하고 있는지 알았다면, 그것은 연구라고 부르지 않았을 것이다."[NEWLINE] - 알버트 아인슈타인[NEWLINE]');
--======================================================================================================================
INSERT INTO Language_en_US 
				(Tag,										Text) 
SELECT DISTINCT	'TXT_KEY_BUILDING_'||b.WType||'_HELP_CUT',	Text
FROM Language_en_US a, JHWfVPConfig b WHERE a.Tag = 'TXT_KEY_BUILDING_'||b.WType||'_HELP';
